import {makeAutoObservable} from "mobx";

export default class DishStore{
    constructor(){
        this._types = [
            {id: 1, name: 'Суші'},
            {id: 2, name: 'Роли'},
            {id: 3, name: 'Напої'}
        ]
        this._dishes=[
            {id: 1,	name: "Козацький драйв", price:	249, img:"aa1e0fdb-e208-43c6-9266-67621ddaac6f.jpg", typeId:2},
            {id: 2,	name: "Сякі-макі", price:	149, img:"462e6877-0d3c-4f17-9e95-3055ca3a4e7d.jpg", typeId:1},
            {id: 3,	name: "Coca-Cola 0.33", price:	29, img:"600be371-aa23-4ee4-ae95-2926287f758b.jpg", typeId:3}
        ]

        this._selectedType = {}

        makeAutoObservable(this)
    }

    setTypes(types){
        this._types = types
    }

    setDishes(dishes){
        this._dishes = dishes
    }

    setSelectedType(type){
        this._selectedType = type
    }

    get types() {
        return this._types
    }

    get dishes(){
        return this._dishes
    }

    get selectedType(){
        return this._selectedType
    }
}
